import { app, BrowserWindow } from 'electron';
import assert from 'node:assert/strict';
const url = process.argv.find(arg => arg.startsWith('http://'));
app.setPath('userData', process.env.LINGXI_TEST_USER_DATA);
const delay = ms => new Promise(resolve => setTimeout(resolve, ms));
async function main() {
  await app.whenReady();
  const window = new BrowserWindow({ show: false, width: 1200, height: 900, webPreferences: { sandbox: true } });
  window.webContents.on('console-message', event => { if (event.message.includes('Error')) process.stderr.write(event.message + '\n'); });
  try {
    await window.loadURL(url);
    const run = script => window.webContents.executeJavaScript(script);
    const wait = async expression => { for (let i = 0; i < 300; i++) { if (await run(expression)) return; await delay(20); } throw new Error(`Timeout: ${expression}\n${await run('document.body.innerText')}`); };
    const exists = selector => wait(`Boolean(document.querySelector(${JSON.stringify(selector)}))`);
    const button = text => run(`Array.from(document.querySelectorAll('button')).find(button => button.textContent.trim() === ${JSON.stringify(text)})?.click()`);
    const state = () => run('window.linkPreviewFixture.state()');
    const show = async (route, payload, scope) => { await run(`window.linkPreviewFixture.show(${JSON.stringify(route)}, ${JSON.stringify(payload)}, ${JSON.stringify(scope)})`); await delay(100); };
    await wait('Boolean(window.linkPreviewFixture)');
    await show('extensions/mcp/known');
    await wait('document.body.innerText.includes("known")');
    assert.ok(await run('document.body.innerText.includes("known")'));
    await show('import/mcp', { name: 'linked-server', config: { command: 'npx', args: ['example'] } });
    await wait('document.body.innerText.includes("Confirm import MCP server")');
    assert.equal((await state()).calls.some(call => call.command.action === 'save_server'), false);
    await run(`document.querySelector('[aria-label="Back to app"]').click()`);
    await exists('[aria-label="Unsaved settings draft"]');
    await button('Continue editing');
    await button('Confirm import MCP server');
    await wait('window.linkPreviewFixture.state().calls.some(call => call.command.action === "save_server")');
    const mcp = (await state()).calls.find(call => call.command.action === 'save_server');
    assert.equal(JSON.parse(mcp.command.payload_json).name, 'linked-server');
    await show('import/skill', { name: 'linked-skill', markdown: '---\ndescription: linked\n---\n# Linked' });
    await wait('document.body.innerText.includes("新建 Skill")');
    assert.equal((await state()).calls.some(call => call.command.action === 'create_skill'), false);
    await run(`document.querySelector('[aria-label="Back to app"]').click()`);
    await exists('[aria-label="Unsaved settings draft"]');
    await button('Continue editing');
    const createLabel = await run('Array.from(document.querySelectorAll("button")).map(button => button.textContent.trim()).find(text => text === "创建 Skill" || text === "创建")');
    assert.ok(createLabel, await run('document.body.innerText'));
    await button(createLabel);
    await wait('window.linkPreviewFixture.state().calls.some(call => call.command.action === "create_skill")');
    await show('import/provider', { providers: { linked: { type: 'openai', baseUrl: 'https://example.com/v1', apiKeyEnv: 'LINKED_KEY', models: [{ id: 'linked-model' }] } } });
    await wait('document.body.innerText.includes("linked")');
    assert.equal((await state()).calls.some(call => call.domain === 'provider'), false);
    assert.ok(await run('document.body.innerText.includes("导入 JSON")'));
    await button('确认导入 1 个 Provider');
    await wait('window.linkPreviewFixture.state().calls.some(call => call.domain === "provider")');
    await show('extensions/plugin/known-plugin');
    await wait('Boolean(document.querySelector(".extension-plugin-page"))');
    assert.ok(await run('document.body.innerText.includes("known-plugin")'));
    await show('extensions/plugin/missing-plugin');
    await wait('document.body.innerText.includes("This plugin is unavailable on this device.")');
    await show('import/plugin', { source: 'owner/marketplace' });
    await wait('document.body.innerText.includes("添加 Marketplace")');
    assert.equal((await state()).calls.some(call => call.command.action === 'apply_operation'), false);
    await button('预检添加');
    await wait('window.linkPreviewFixture.state().calls.some(call => call.command.action === "preview_operation")');
    assert.equal((await state()).calls.some(call => call.command.action === 'apply_operation'), false);
    await button('确认执行');
    await wait('window.linkPreviewFixture.state().calls.some(call => call.command.action === "apply_operation")');
    await run('window.linkPreviewFixture.terminal("echo linked\\necho command")');
    await exists('textarea[aria-label="Linked terminal command"]');
    assert.equal((await state()).terminals, 0);
    assert.equal((await state()).inputs.length, 0);
    await run('window.linkPreviewFixture.toggleTerminal()');
    await delay(30);
    await run('window.linkPreviewFixture.toggleTerminal()');
    await delay(30);
    assert.equal((await state()).terminals, 0, 'hiding/reopening command preview must not start a shell');
    await button('Cancel');
    assert.equal((await state()).inputs.length, 0);
    await run('window.linkPreviewFixture.terminal("echo original")');
    await exists('textarea[aria-label="Linked terminal command"]');
    await run(`(() => { const textarea = document.querySelector('textarea[aria-label="Linked terminal command"]'); Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set.call(textarea, 'echo edited'); textarea.dispatchEvent(new Event('input', { bubbles: true })); })()`);
    await button('Confirm and run');
    await wait('window.linkPreviewFixture.state().inputs.length === 1');
    assert.equal((await state()).inputs[0], '\x1b[200~echo edited\x1b[201~\r');
    await run('window.linkPreviewFixture.cron("run", "run-1")');
    await exists('[id="scheduled-run-run-1"][aria-current="true"]');
    assert.ok(await run('document.body.innerText.includes("Linked run result")'));
    assert.equal((await state()).calls.filter(call => call.domain === 'cron').every(call => call.command.action === 'list'), true);
    await run(`(() => { const input = document.querySelector('.scheduled-setup-title'); Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set.call(input, 'Keep my task draft'); input.dispatchEvent(new Event('input', { bubbles: true })); })()`);
    await delay(30);
    await run('window.linkPreviewFixture.cron("job", "job-1")');
    await exists('[role="alertdialog"][aria-label="Unsaved changes"]');
    assert.equal(await run('document.querySelector(".scheduled-setup-title").value'), 'Keep my task draft');
    await run('window.linkPreviewFixture.stage("result-second")');
    await wait('window.linkPreviewFixture.state().located.at(-1) === true');
    assert.ok(await run(`document.querySelector('[data-message-uuid="result-second"]').dataset.messageUuids.includes('call-first')`));
    assert.equal(await run(`document.querySelector('button[aria-label="Copy message link"]') === null`), true);
    assert.deepEqual((await state()).copiedUuids, []);
    await run('window.linkPreviewFixture.stage("hidden-message")');
    await exists('[data-message-uuid="hidden-message"]');
    await wait('window.linkPreviewFixture.state().located.length === 2');
    assert.deepEqual((await state()).located, [true, true], 'folded targets must reveal before reporting locator success');
    const beforeStream = (await state()).scrolls;
    await run('window.linkPreviewFixture.stream()');
    await delay(100);
    assert.equal((await state()).scrolls, beforeStream, 'streaming must not repeat message scroll');
    await run('window.linkPreviewFixture.stage("reasoning-message")');
    await exists('[data-message-uuid="reasoning-message"]');
    assert.ok(await run('document.body.innerText.includes("Persisted reasoning-only target")'));
    assert.deepEqual((await state()).located, [true, true, true]);
    process.stdout.write(JSON.stringify({ passed: true }) + '\n');
  } finally { window.destroy(); app.quit(); }
}
main().catch(error => { process.stderr.write(`${error.stack ?? error}\n`); app.exit(1); });
